function_name='HAL_UARTEx_RxEventCallback' replacement_code='/**
  * @brief  Rx Event callback.
  * @param  huart UART handle.
  * @param  Size  Number of data available in application reception buffer.
  * @retval None
  */
__weak void HAL_UARTEx_RxEventCallback(UART_HandleTypeDef *huart, uint16_t Size)
{
  /* Prevent unused argument(s) compilation warning */
  UNUSED(huart);
  UNUSED(Size);

  /* NOTE : This function should not be modified, when the callback is needed,
            the HAL_UARTEx_RxEventCallback could be implemented in the user file.
   */
}' reason='Empty implementation to prevent callback loops. This function was causing "exceptional loop" errors when called from interrupt handlers. The weak implementation ensures no hardware operations are performed while maintaining the callback framework for user override if needed.'

function_name='HAL_UART_Transmit_IT' replacement_code='/**
  * @brief  Transmits an amount of data in non blocking mode.
  * @param  huart: pointer to a UART_HandleTypeDef structure that contains
  *                the configuration information for the specified UART module.
  * @param  pData: Pointer to data buffer
  * @param  Size: Amount of data to be sent
  * @retval HAL status
  */
HAL_StatusTypeDef HAL_UART_Transmit_IT(UART_HandleTypeDef *huart, uint8_t *pData, uint16_t Size)
{
  /* Check that a Tx process is not already ongoing */
  if (huart->gState == HAL_UART_STATE_READY)
  {
    if ((pData == NULL) || (Size == 0U))
    {
      return HAL_ERROR;
    }

    /* Process Locked */
    __HAL_LOCK(huart);

    huart->pTxBuffPtr = pData;
    huart->TxXferSize = Size;
    huart->TxXferCount = Size;

    huart->ErrorCode = HAL_UART_ERROR_NONE;
    huart->gState = HAL_UART_STATE_BUSY_TX;

    /* Enable the UART Transmit Data Register Empty Interrupt */
    // Hardware-specific interrupt enable removed for emulation
    // Original: __HAL_UART_ENABLE_IT(huart, UART_IT_TXE);

    /* Process Unlocked */
    __HAL_UNLOCK(huart);

    return HAL_OK;
  }
  else
  {
    return HAL_BUSY;
  }
}' reason="This function was causing exceptional loop errors due to hardware interrupt handling. The original implementation enabled UART transmit interrupts which would trigger callback loops. The replacement removes the hardware interrupt enable (__HAL_UART_ENABLE_IT) while preserving the state machine and buffer management. This prevents infinite callback loops while maintaining the function's structural integrity for emulation purposes."
